#include <iostream>
#include <memory>

// Public declaration: normally Counter.hpp.
class Counter {
public:
    Counter();
    ~Counter();
    Counter(const Counter&) = delete;
    Counter& operator=(const Counter&) = delete;
    void increment();
    int value() const;
private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};

// Implementation: normally Counter.cpp.
struct Counter::Impl { int count{}; };
Counter::Counter() : impl_{std::make_unique<Impl>()} {}
Counter::~Counter() = default;
void Counter::increment() { ++impl_->count; }
int Counter::value() const { return impl_->count; }

int main()
{
    Counter counter;
    counter.increment();
    std::cout << counter.value() << '\n';
}
